      line-height: 1.05;
    }

    .intro {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq-list {
      display: grid;
      gap: 16px;
    }

    .example {
      background: linear-gradient(180deg, rgba(19, 27, 52, 0.95), rgba(12, 18, 37, 0.95));
      border: 1px solid var(--panel-border);
      border-radius: 22px;
      overflow: hidden;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
      transition: border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;
    }

    .example:hover {
      border-color: rgba(125, 211, 252, 0.28);
      transform: translateY(-1px);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.05),
        0 16px 32px rgba(7, 11, 22, 0.28);
    }

    .question {
      width: 100%;
      border: 0;
      background: transparent;
      color: inherit;
      font: inherit;
      padding: 22px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      cursor: pointer;
      text-align: left;
    }

    .question-text {
      font-size: 1.05rem;
      font-weight: 650;
      letter-spacing: 0.01em;
    }

    .icon {
      width: 34px;
      height: 34px;
      flex: 0 0 auto;
      border-radius: 999px;
      display: grid;
      place-items: center;
      color: var(--accent);
      background: rgba(125, 211, 252, 0.08);
      border: 1px solid rgba(125, 211, 252, 0.14);
      transition: transform 180ms ease, background-color 180ms ease;
      font-size: 1.2rem;
      line-height: 1;
