    .question[aria-expanded="true"] .icon {
      transform: rotate(45deg);
      background: rgba(56, 189, 248, 0.16);
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

    .details.open {
      grid-template-rows: 1fr;
    }

    .details-inner {
      min-height: 0;
      overflow: hidden;
    }

    .answer {
      margin: 0;
      padding: 0 24px 24px;
      color: var(--muted);
      line-height: 1.75;
      font-size: 0.98rem;
    }

    @media (max-width: 640px) {
      .shell {
        padding: 22px;
        border-radius: 22px;
      }

      .question {
        padding: 18px 18px;
      }

      .answer {
        padding: 0 18px 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const faqItems = [
      {
        question: "Why do cats purr?",
        answer:
          "Cats often purr when they feel comfortable and safe, but they can also purr to self-soothe when stressed or recovering. The sound is thought to be linked to rhythmic muscle activity in the larynx.",
      },
      {
        question: "How much sleep do cats need?",
        answer:
          "Most adult cats sleep between 12 and 16 hours a day, and some nap even longer. Their sleep-heavy routine reflects their instinct as crepuscular hunters that conserve energy for short bursts of activity.",
      },
      {
        question: "Why do cats knead blankets and laps?",
        answer:
          "Kneading starts in kittenhood as a nursing behavior and often carries into adulthood as a sign of comfort. Many cats do it when they are relaxed, settling in, or marking a favorite spot with scent glands in their paws.",
      },
      {
        question: "Do cats need vertical spaces at home?",
        answer:
          "Yes. Cat trees, shelves, and window perches help cats feel secure, observe their surroundings, and stay active. Vertical territory is especially helpful in smaller homes or multi-cat households.",
      },
      {
        question: "What is the best way to keep a cat entertained?",
        answer:
          "Rotate interactive toys, schedule short play sessions with wand toys, and add puzzle feeders or climbing spots. Cats usually respond best to toys that mimic prey movement rather than constant passive stimulation.",
      },
      {
        question: "How can you tell if a cat is happy?",
        answer:
          "Relaxed body posture, slow blinking, a loosely upright tail, playful behavior, and a healthy appetite are all encouraging signs. A content cat also tends to seek comfortable resting places and interact on its own terms.",
      },
    ];

    const createElement = (tag, className, text) => {
      const element = document.createElement(tag);
      if (className) {
        element.className = className;
      }
      if (text) {
        element.textContent = text;
      }
      return element;
    };

    function Header() {
      const header = createElement("header", "hero");
      const eyebrow = createElement("div", "eyebrow", "Cat Care FAQ");
      const title = createElement("h1", "", "Everything you wanted to ask about cats");
      const intro = createElement(
        "p",
        "intro",
        "Browse quick answers to common cat questions. Each topic starts collapsed, so you can expand only the details you want."
      );

      header.append(eyebrow, title, intro);
      return header;
    }

    function FAQItem({ question, answer }, index) {
      const wrapper = createElement("div", "example");
      const button = createElement("button", "question");
      const text = createElement("span", "question-text", question);
      const icon = createElement("span", "icon", "+");
      const details = createElement("div", "details");
      const inner = createElement("div", "details-inner");
      const answerText = createElement("p", "answer", answer);

      const detailsId = `faq-panel-${index}`;

      button.type = "button";
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-controls", detailsId);
      details.id = detailsId;
      details.hidden = true;

      button.addEventListener("click", () => {
        const isOpen = button.getAttribute("aria-expanded") === "true";
        button.setAttribute("aria-expanded", String(!isOpen));
        details.hidden = isOpen;
        details.classList.toggle("open", !isOpen);
      });

      button.append(text, icon);
      inner.append(answerText);
      details.append(inner);
      wrapper.append(button, details);
      return wrapper;
    }

    function FAQList(items) {
      const list = createElement("section", "faq-list");
      items.forEach((item, index) => list.append(FAQItem(item, index)));
      return list;
    }

    function App() {
      const shell = createElement("main", "shell");
      shell.append(Header(), FAQList(faqItems));
      return shell;
    }

    document.getElementById("app").append(App());
  </script>
</body>
</html>
